package insane96mcp.runeenchanting.setup;

import insane96mcp.runeenchanting.RuneEnchanting;
import net.minecraft.core.registries.Registries;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.sounds.SoundEvent;
import net.minecraft.sounds.SoundEvents;
import net.neoforged.neoforge.registries.DeferredHolder;
import net.neoforged.neoforge.registries.DeferredRegister;

import java.util.ArrayList;
import java.util.List;

/**
 * The mod's sound events. They all play a vanilla sound event (see sounds.json, generated by RESoundDefinitionsProvider)
 * but have their own subtitles.
 */
public class RESoundEvents {
    public static final DeferredRegister<SoundEvent> REGISTRY = DeferredRegister.create(Registries.SOUND_EVENT, RuneEnchanting.MOD_ID);

    /** Every sound registered here, with the vanilla sound event it plays and its subtitle. Used by data generation. */
    public static final List<SoundInfo> SOUNDS = new ArrayList<>();

    public static final DeferredHolder<SoundEvent, SoundEvent> CURSE_LEARNED = register("curse_learned", SoundEvents.PLAYER_LEVELUP, "Curse learned");
    public static final DeferredHolder<SoundEvent, SoundEvent> RUNIC_TABLE_STORE = register("block.runic_table.store", SoundEvents.CHISELED_BOOKSHELF_INSERT_ENCHANTED, "Rune stored");
    public static final DeferredHolder<SoundEvent, SoundEvent> RUNIC_TABLE_APPLY = register("block.runic_table.apply", SoundEvents.ENCHANTMENT_TABLE_USE, "Rune applied");
    public static final DeferredHolder<SoundEvent, SoundEvent> RUNIC_TABLE_REMOVE = register("block.runic_table.remove", SoundEvents.GRINDSTONE_USE, "Rune removed");
    public static final DeferredHolder<SoundEvent, SoundEvent> DOUBLE_JUMP = register("rune.double_jump", SoundEvents.FIREWORK_ROCKET_LAUNCH, "Player double jumps");
    public static final DeferredHolder<SoundEvent, SoundEvent> EXECUTIONER = register("rune.executioner", SoundEvents.PLAYER_ATTACK_CRIT, "Executioner strikes");
    public static final DeferredHolder<SoundEvent, SoundEvent> EXPLOSIVE = register("rune.explosive", SoundEvents.TNT_PRIMED, "Explosive rune primes");
    public static final DeferredHolder<SoundEvent, SoundEvent> FIRE_GUARDIAN = register("rune.fire_guardian", SoundEvents.FIRE_EXTINGUISH, "Fire Guardian activates");
    public static final DeferredHolder<SoundEvent, SoundEvent> LAPIS_FUELED_CONSUME = register("rune.lapis_fueled.consume", SoundEvents.AMETHYST_BLOCK_CHIME, "Lapis consumed");
    public static final DeferredHolder<SoundEvent, SoundEvent> LAPIS_FUELED_RUN_OUT = register("rune.lapis_fueled.run_out", SoundEvents.BEACON_DEACTIVATE, "Lapis runs out");
    public static final DeferredHolder<SoundEvent, SoundEvent> MOMENTUM = register("rune.momentum", SoundEvents.PLAYER_LEVELUP, "Momentum increases");
    public static final DeferredHolder<SoundEvent, SoundEvent> SHATTERBURST = register("rune.shatterburst", SoundEvents.SHIELD_BREAK, "Arrow shatters");
    public static final DeferredHolder<SoundEvent, SoundEvent> TELEKINESIS = register("rune.telekinesis", SoundEvents.ITEM_PICKUP, "Item pulled");
    public static final DeferredHolder<SoundEvent, SoundEvent> CURSE_OF_ENDER = register("rune.curse_of_ender", SoundEvents.CHORUS_FRUIT_TELEPORT, "Cursed entity teleports");
    public static final DeferredHolder<SoundEvent, SoundEvent> CURSE_OF_SLIPPERINESS = register("rune.curse_of_slipperiness", SoundEvents.ALLAY_HURT, "Item slips");

    private static DeferredHolder<SoundEvent, SoundEvent> register(String name, SoundEvent vanillaSound, String subtitle) {
        DeferredHolder<SoundEvent, SoundEvent> holder = REGISTRY.register(name, () -> SoundEvent.createVariableRangeEvent(RuneEnchanting.id(name)));
        SOUNDS.add(new SoundInfo(holder, vanillaSound.getLocation(), "subtitles." + RuneEnchanting.MOD_ID + "." + name, subtitle));
        return holder;
    }

    public record SoundInfo(DeferredHolder<SoundEvent, SoundEvent> sound, ResourceLocation vanillaSound, String subtitleKey, String subtitle) {}
}
